17	export function validateRanking(params: ValidateRankingParams): string[] {
18	  const { isNewJobMode, jobDescription, fileCount, subscriptionCredits, topupCredits, totalCredits, maxResumes, isAuthenticated } = params;
19	  const errors: string[] = [];
20	
21	  if (isNewJobMode && !jobDescription.trim()) {
22	    errors.push("Job description is required.");
23	  }
24	
25	  if (fileCount === 0) {
26	    errors.push("Upload at least one resume.");
27	  }
28	
29	  if (isAuthenticated) {
30	    const splitTotal = subscriptionCredits + topupCredits;
31	    const effectiveCredits = splitTotal > 0 ? splitTotal : totalCredits;
32	    const required = Math.min(fileCount, maxResumes);
33	    if (effectiveCredits < required) {
34	      errors.push(`Not enough credits. You need ${required} but have ${effectiveCredits}.`);
35	    }
36	  }
37	
38	  return errors;
